import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const g=JSON.parse('{"title":"RabbitMQ Publisher Message Type Compatibility & Graceful Media Stream Disconnect Handling","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.md","filePath":"feature/modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.md"}'),s={name:"feature/modules/07-billing-publisher-and-observability/social-publisher-resilience/spec.md"};function r(n,e,c,d,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Master Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="rabbitmq-publisher-message-type-compatibility-graceful-media-stream-disconnect-handling" tabindex="-1">RabbitMQ Publisher Message Type Compatibility &amp; Graceful Media Stream Disconnect Handling <a class="header-anchor" href="#rabbitmq-publisher-message-type-compatibility-graceful-media-stream-disconnect-handling" aria-label="Permalink to &quot;RabbitMQ Publisher Message Type Compatibility &amp; Graceful Media Stream Disconnect Handling&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Module Slug</strong></td><td style="text-align:left;"><code>social-publisher-resilience</code></td></tr><tr><td style="text-align:left;"><strong>Category</strong></td><td style="text-align:left;"><code>07-billing-publisher-and-observability</code> — Billing Verification, Publisher Resilience &amp; System Health Observability</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner, Manager, Creator, Client</code></td></tr><tr><td style="text-align:left;"><strong>Consolidated Feature Scopes</strong></td><td style="text-align:left;"><code>publisher-message-type-compatibility</code>, <code>media-disconnect-handling</code></td></tr><tr><td style="text-align:left;"><strong>Aligned SRS Domains</strong></td><td style="text-align:left;"><a href="./../../../srs/07-publishing-social/README.html">3.8 Publishing &amp; Social</a> (<code>3.8.4</code>, <code>3.8.7–3.8.15</code>) · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified</td></tr></tbody></table><h2 id="_1-objective-architectural-motivation" tabindex="-1">1. Objective &amp; Architectural Motivation <a class="header-anchor" href="#_1-objective-architectural-motivation" aria-label="Permalink to &quot;1. Objective &amp; Architectural Motivation&quot;">​</a></h2><p>Harden cross-service messaging and media streaming resilience across <code>brandhub-business-service</code> and <code>brandhub-publisher-service</code>: ensuring zero-downtime <strong>Jackson <code>__TypeId__</code> RabbitMQ deserialization compatibility</strong> (<code>publisher-message-type-compatibility</code>) between producer and consumer DTO packages, and handling <strong>abrupt browser/mobile media stream disconnects</strong> (<code>media-disconnect-handling</code>) cleanly without false <code>500</code> alerts or converter exceptions.</p><h2 id="_2-user-stories" tabindex="-1">2. User Stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User Stories&quot;">​</a></h2><ul><li>As an <code>Owner</code>, <code>Manager</code>, or <code>Creator</code> publishing posts, I want RabbitMQ <code>PublishJobMessage</code> payloads emitted by <code>business-service</code> to deserialize reliably in <code>publisher-service</code> across rolling deployments without poison-message loops.</li><li>As any user scrubbing or closing HTML5/native video previews, I want aborted HTTP range streams (<code>Broken pipe</code> / <code>ClientAbortException</code> / <code>AsyncRequestNotUsableException</code>) handled quietly without corrupting server error metrics.</li></ul><h2 id="_3-consolidated-acceptance-criteria" tabindex="-1">3. Consolidated Acceptance Criteria <a class="header-anchor" href="#_3-consolidated-acceptance-criteria" aria-label="Permalink to &quot;3. Consolidated Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Cross-Service RabbitMQ <code>__TypeId__</code> Mapping (<code>publisher-message-type-compatibility</code>):</strong> <code>com.brandhub.publisher.common.config.RabbitMQConfig.jsonMessageConverter()</code> configures <code>DefaultClassMapper</code> + <code>Jackson2JsonMessageConverter</code> mapping producer header <code>com.brandhub.business.dto.message.PublishJobMessage</code> (and legacy/fallback empty type headers) directly to <code>com.brandhub.publisher.core.dto.PublishJobMessage</code>, ignoring unknown forward-compatible fields (<code>FAIL_ON_UNKNOWN_PROPERTIES = false</code>).</li><li><strong>Dual Token Field Compatibility in <code>PublishJobConsumer</code>:</strong> Normalizes <code>accessToken</code> &lt;-&gt; <code>encryptedToken</code> fields on arrival and rejects malformed payloads lacking <code>postId</code>/<code>jobId</code> via <code>basicNack(requeue=false)</code> + <code>AmqpRejectAndDontRequeueException</code> so poison messages route cleanly to <code>publisher.job.dlq</code> instead of spinning CPU.</li><li><strong>Graceful Media Streaming Client Disconnect (<code>media-disconnect-handling</code>):</strong> Global exception handling in <code>brandhub-business-service</code> detects client-initiated socket closes (<code>AsyncRequestNotUsableException</code>, <code>ClientAbortException</code>, <code>EOFException</code> / <code>Broken pipe</code> on <code>/repository-media</code>, <code>/videos/{jobId}/content</code>, <code>/attachments/{id}/content</code>), suppresses JSON <code>ApiResponse</code> write attempts onto already-committed <code>video/mp4</code> / <code>octet-stream</code> responses, and logs at <code>DEBUG</code> instead of <code>ERROR</code>.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> Every user-facing string, tooltip, dialog prompt, status badge, and error banner uses key-parallel translations (Backend/protocol resilience module; existing localized media error banners (<code>common.errors.mediaLoadFailed</code>) in <code>vi.json</code> &amp; <code>en.json</code> preserved) on <code>brandhub-web</code> and <code>tr()</code> (<code>en.json</code> + <code>vi/common.json</code>) on <code>brandhub-mobile-app</code> with zero hardcoded Vietnamese or English strings in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All surfaces, drawers, badges, charts, and interactive controls use semantic CSS variables / Tailwind <code>dark:</code> variants on Web and <code>useAppPreferences().palette</code> tokens on Mobile, achieving WCAG AA contrast in both Light and Dark themes.</li></ol><h2 id="_4-ui-ux-surfaces-lifecycle-states" tabindex="-1">4. UI / UX Surfaces &amp; Lifecycle States <a class="header-anchor" href="#_4-ui-ux-surfaces-lifecycle-states" aria-label="Permalink to &quot;4. UI / UX Surfaces &amp; Lifecycle States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/editor/*</code>, <code>pages/library/*</code>, <code>pages/video-space/*</code> HTML5 <code>&lt;video&gt;</code> players</li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>expo-video</code> players across <code>PostDetailScreen.tsx</code>, <code>AiVideoHistoryScreen.tsx</code>, <code>MediaLibraryScreen.tsx</code></li><li><strong>UI States:</strong><ul><li><strong>Loading / Streaming:</strong> Deterministic skeleton placeholders, progress bars, and disabled submit buttons preventing duplicate requests.</li><li><strong>Empty / Onboarding:</strong> Contextual empty state with localized call-to-action and zero fabricated mock fallback data.</li><li><strong>Active / Realtime Sync:</strong> Scoped <code>TanStack Query</code> cache updates + WebSocket/SSE/polling synchronization where applicable.</li><li><strong>Error / Conflict Recovery:</strong> Actionable localized error banners (<code>400/403/404/409/429/503</code>) preserving unsaved user input.</li></ul></li></ul><h2 id="_5-api-messaging-protocol-contract" tabindex="-1">5. API, Messaging &amp; Protocol Contract <a class="header-anchor" href="#_5-api-messaging-protocol-contract" aria-label="Permalink to &quot;5. API, Messaging &amp; Protocol Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Route / Channel / Filter</th><th style="text-align:left;">Auth / Scope</th><th style="text-align:left;">Service &amp; Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>AMQP publisher.job.exchange -&gt; publisher.job.queue</code></td><td style="text-align:left;">RabbitMQ Internal Broker</td><td style="text-align:left;"><code>PublishJobConsumer</code> + <code>RabbitMQConfig.jsonMessageConverter()</code> (<code>DefaultClassMapper</code>)</td></tr><tr><td style="text-align:left;"><code>GET /api/v1/repository-media &amp; /workspaces/*/ai/videos/{jobId}/content</code></td><td style="text-align:left;">Authorized Media Stream</td><td style="text-align:left;"><code>RepositoryEncryptedMediaController</code>, <code>AiVideoController</code>, <code>GlobalExceptionHandler</code> -&gt; quiet client-abort handling</td></tr></tbody></table><h2 id="_6-error-handling-security-edge-cases" tabindex="-1">6. Error Handling, Security &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-security-edge-cases" aria-label="Permalink to &quot;6. Error Handling, Security &amp; Edge Cases&quot;">​</a></h2><ul><li><strong>Rolling Deploy New Field Added on <code>business-service</code> First:</strong> Consumer ignores unknown JSON property safely and continues publishing.</li><li><strong>Safari / iOS Range Probe Immediate Abort:</strong> Byte-range <code>0-1</code> probe followed by socket close returns cleanly with <code>0</code> <code>HttpMessageNotWritableException</code> stack traces.</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Aligned SRS Functional Requirements:</strong> <a href="./../../../srs/07-publishing-social/README.html">3.8 Publishing &amp; Social</a> (<code>3.8.4</code>, <code>3.8.7–3.8.15</code>) · <a href="./../../../srs/06-ai-features/3-7-12-export-file/spec.html">FR 3.7.12 — Export File</a></li><li><strong>BA &amp; Architecture References:</strong> <a href="./../../../../ba/07-publishing-social.html">BA 07 Publishing &amp; Social</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Production code verified across backend, AI/publisher workers, Web, and Mobile; <code>vi.json</code> + <code>en.json</code> parity verified; Light/Dark mode audited; all automated verification suites in <a href="./test.html">test.md</a> passing.</li><li><strong>Out of Scope:</strong> De-scoped SRS items (livestream features, subscription plan downgrades, PayOS/VNPay/Stripe gateways, Zalo OA publishing, or copyright/plagiarism scanning).</li></ul>',19)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
